@Composable
private fun BookCard(
    title: String,
    author: String,
    coverPath: String?,
    spineColor: Color,
    progressPercent: Float,
    detail: String,
    onClick: () -> Unit
) {
    Column(
        modifier = Modifier
            .width(CARD_WIDTH)
            .clip(RoundedCornerShape(8.dp))
            .clickable(onClick = onClick)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(COVER_ASPECT)
                .clip(RoundedCornerShape(6.dp))
                .background(HomePanel)
        ) {
            if (!coverPath.isNullOrBlank()) {
                AsyncImage(
                    model = coverPath,
                    contentDescription = title,
                    contentScale = ContentScale.Crop,
                    modifier = Modifier.fillMaxSize()
                )
            } else {
                BookCoverFallback(title = title, author = author, spineColor = spineColor)
            }
        }
        Spacer(Modifier.height(8.dp))
        Text(
            text = title,
            style = ShelfTypography.LabelSmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
            fontWeight = FontWeight.SemiBold,
            color = HomeFg,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )
        if (author.isNotBlank()) {
            Spacer(Modifier.height(2.dp))
            Text(
                text = author,
                style = ShelfTypography.LabelSmall,
                color = HomeDim,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
        Spacer(Modifier.height(6.dp))
        ThinProgressBar(progress = progressPercent)
        Spacer(Modifier.height(4.dp))
        Text(
            text = detail,
            style = ShelfTypography.LabelSmall,
            color = HomeDim,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
    }
}

@Composable
private fun BookCoverFallback(title: String, author: String, spineColor: Color) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    listOf(
                        lerp(spineColor, Color.White, 0.20f),
                        spineColor,
                        lerp(spineColor, Color.Black, 0.32f)
                    )
                )
            )
    ) {
        Box(
            Modifier
                .fillMaxHeight()
                .width(4.dp)
                .background(Color.Black.copy(alpha = 0.25f))
        )
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(start = 12.dp, end = 10.dp, top = 10.dp, bottom = 10.dp)
        ) {
            Text(
                text = title,
                style = ShelfTypography.LabelSmall.copy(fontSize = 10.sp, lineHeight = 13.sp),
                fontWeight = FontWeight.Bold,
                color = Color.White.copy(alpha = 0.95f),
                maxLines = 3,
                overflow = TextOverflow.Ellipsis
            )
            Spacer(Modifier.weight(1f))
            if (author.isNotBlank()) {
                Text(
                    text = author,
